window.proc2ConfigureAdmission=function(){var r=S.admissionRules,allowed=r.allowedStatuses;openModal('玉米淀粉供应商准入标准配置','<div class="proc2-form-grid"><label class="proc2-field">最低质检合格率（%）<input id="proc2-rule-quality" type="number" min="0" max="100" step="0.1" value="'+r.qualityMin+'"></label><label class="proc2-field">最低准时交付率（%）<input id="proc2-rule-otd" type="number" min="0" max="100" step="0.1" value="'+r.onTimeMin+'"></label><label class="proc2-field">最大综合风险分<input id="proc2-rule-risk" type="number" min="0" max="100" value="'+r.riskMax+'"></label><label class="proc2-field">资质提前预警天数<input id="proc2-rule-days" type="number" min="0" max="365" value="'+r.qualificationAlertDays+'"></label><div class="proc2-field span-2"><span>允许进入候选池的状态</span><div class="proc2-checks"><label class="proc2-check"><input id="proc2-rule-status-accepted" type="checkbox" '+(allowed.indexOf('准入')>=0?'checked':'')+'>准入</label><label class="proc2-check"><input id="proc2-rule-status-limited" type="checkbox" '+(allowed.indexOf('限制')>=0?'checked':'')+'>限制</label><label class="proc2-check"><input id="proc2-rule-status-paused" type="checkbox" '+(allowed.indexOf('暂停')>=0?'checked':'')+'>暂停</label></div></div><label class="proc2-field span-3">维护说明<textarea id="proc2-rule-note">'+esc(r.note)+'</textarea></label></div><div class="proc2-alert mt-16"><b>生效范围：</b>保存后立即重新判定资料库、供应商画像、当期候选池和评价预警；已发布采购方案继续使用发布时的规则快照。</div>','<button class="btn btn-sm" onclick="proc2CloseModal()">取消</button><button class="btn btn-sm btn-primary" onclick="proc2SaveAdmissionRules()">保存并生效</button>','820px');};
window.proc2SaveAdmissionRules=function(){var quality=Number(document.getElementById('proc2-rule-quality').value),otd=Number(document.getElementById('proc2-rule-otd').value),risk=Number(document.getElementById('proc2-rule-risk').value),days=Number(document.getElementById('proc2-rule-days').value),statuses=[];if(document.getElementById('proc2-rule-status-accepted').checked)statuses.push('准入');if(document.getElementById('proc2-rule-status-limited').checked)statuses.push('限制');if(document.getElementById('proc2-rule-status-paused').checked)statuses.push('暂停');if(quality<0||quality>100||otd<0||otd>100||risk<0||risk>100||days<0||days>365||!statuses.length){toast('请检查准入阈值，且至少选择一个允许状态','red');return;}var seq=Number((S.admissionRules.version.match(/V(\d+)$/)||[])[1]||1)+1;S.admissionRules={version:'ADM-20260929-V'+seq,qualityMin:quality,onTimeMin:otd,riskMax:risk,qualificationAlertDays:Math.round(days),allowedStatuses:statuses,updatedAt:'2026-09-29 10:15',updatedBy:'李明哲',note:document.getElementById('proc2-rule-note').value.trim()||'人工维护准入标准'};S.candidates=new Set(Array.from(S.candidates).filter(function(id){var s=supplier(id);return s&&statuses.indexOf(s.status)>=0;}));S.params.mandatory=S.params.mandatory.filter(function(id){return S.candidates.has(id);});S.solutions=[];S.solverMeta=null;closeModal();render();toast('准入标准 '+S.admissionRules.version+' 已保存并生效');};
window.proc2ViewMilp=function(){var meta=S.solverMeta;if(!meta)return;var m=meta.model,rows=m.list.map(function(s){return '<tr><td>'+s.shortName+'</td><td class="num">'+fmt(unitCost(s,m.params.rate),2)+'</td><td class="num">'+fmt(Math.max(Number(s.moq||0),m.minQty))+'</td><td class="num">'+fmt(Math.min(Number(s.periodCapacity||0),m.maxQty))+'</td><td>'+((m.mandatory.indexOf(s.id)>=0)?tag('必选','purple'):tag('可选','gray'))+'</td></tr>';}).join('');openModal('玉米淀粉采购优化 MILP 模型','<div class="proc2-model-formula"><b>目标函数</b><code>min Σ(cᵢ × xᵢ)</code><small>cᵢ = 报价 + 运费 − 账期资金节省 − 包装袋抵扣</small></div><div class="proc2-model-equations"><div><b>需求平衡</b><code>Σxᵢ = '+fmt(m.demand)+'</code></div><div><b>供应商数量</b><code>Σyᵢ ≥ '+m.params.minCount+'</code></div><div><b>数量上界</b><code>xᵢ ≤ min(可供量, '+m.params.maxShare+'% × 需求) × yᵢ</code></div><div><b>数量下界</b><code>xᵢ ≥ max(MOQ, '+m.params.minShare+'% × 需求) × yᵢ</code></div></div><div class="proc2-table-wrap mt-16"><table class="proc2-table"><thead><tr><th>供应商</th><th>cᵢ 综合单价</th><th>入选下界/吨</th><th>入选上界/吨</th><th>选择约束</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="proc2-alert success mt-16"><b>求解方式：</b>'+meta.method+'。启发式产生 '+meta.heuristicFeasible+' 个可行解；'+(meta.exactSkipped?'当前规模未执行精确校验。':'小规模精确检查 '+meta.exactChecked+' 个供应商组合，最优性差距 '+(meta.gap==null?'—':meta.gap.toFixed(2)+'%')+'。')+'</div>','<button class="btn btn-sm btn-primary" onclick="proc2CloseModal()">关闭</button>','980px');};
